+// dropSnapshot deletes snapshot id, just taken of mc, that nothing uses;
+// mc's newest snapshot goes back to prev.
+func (m *Manager) dropSnapshot(mc *machine, id, prev string) {
+	m.mu.Lock()
+	delete(m.snaps, id)
+	m.mu.Unlock()
+	os.RemoveAll(m.snapDir(id))
+	mc.mu.Lock()
+	if mc.Last == id {
+		mc.Last = prev
+		m.saveMachine(mc)
+	}
+	mc.mu.Unlock()
+}
